import { NextRequest, NextResponse } from "next/server";
import { getApiUrl } from "@/lib/utils";

// The pass is generated by the api-server (same code that later sends the
// updates, with the active season's art). This used to be a second copy of the
// generator with its own assets, so new cards came out with a different design.
// Kept as a redirect because the public pages and already-printed QRs use it.
export async function GET(_request: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const apiBase = process.env.API_SERVER_URL || getApiUrl();
  return NextResponse.redirect(`${apiBase}/api/wallet/pass/${encodeURIComponent(id)}`, 307);
}
